import { FunctionsHttpError } from '@supabase/supabase-js';
import { supabase } from './supabase';

export type PosPaymentStatus = 'pending' | 'processing' | 'paid' | 'failed' | 'cancelled' | 'expired';

export type PosCheckoutItem = {
  id: string;
  name: string;
  image_url?: string;
  type?: string;
  quantity: number;
  price: number;
  discount?: number;
  line_subtotal?: number;
  line_discount?: number;
  line_total?: number;
};

export type PublicPosCheckout = {
  id: string;
  user_id: string;
  system_name: string;
  items: PosCheckoutItem[];
  subtotal_amount: number;
  discount_amount: number;
  tax_amount: number;
  tax_rate: number;
  total_amount: number;
  currency: string;
  status: PosPaymentStatus;
  receipt_number: string | null;
  payment_method: string | null;
  paid_at: string | null;
  created_at: string;
  expires_at: string;
  merchant: {
    username: string | null;
    name: string;
    avatar_url: string | null;
    location: string;
    success_message: string;
  };
};

export class PosPaymentError extends Error {
  code?: string;

  constructor(message: string, code?: string) {
    super(message);
    this.name = 'PosPaymentError';
    this.code = code;
  }
}

export async function invokePosPayments<T>(
  action: string,
  input: Record<string, unknown> = {},
): Promise<T> {
  const { data, error } = await supabase.functions.invoke('pos-payments', {
    body: { action, ...input },
  });

  if (error) {
    if (error instanceof FunctionsHttpError) {
      try {
        const payload = await error.context.json();
        throw new PosPaymentError(payload?.error || error.message, payload?.code);
      } catch (contextError) {
        if (contextError instanceof PosPaymentError) throw contextError;
      }
    }
    throw new PosPaymentError(error.message || 'The POS service is temporarily unavailable.');
  }
  if (data?.error) throw new PosPaymentError(data.error, data.code);
  return data as T;
}

export function formatPosMoney(amount: number, currency = 'EUR', locale?: string) {
  return new Intl.NumberFormat(locale || undefined, {
    style: 'currency',
    currency: currency.toUpperCase(),
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(Number(amount || 0));
}

export function formatPosDate(value: string | Date, locale?: string) {
  const date = value instanceof Date ? value : new Date(value);
  return new Intl.DateTimeFormat(locale || undefined, {
    weekday: 'short',
    day: '2-digit',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  }).format(date);
}

export function posPaymentLabel(status: string) {
  switch (status) {
    case 'paid': return 'Paid';
    case 'processing': return 'Processing';
    case 'failed': return 'Failed';
    case 'cancelled': return 'Cancelled';
    case 'expired': return 'Expired';
    default: return 'Awaiting payment';
  }
}
